export type CollapsePlan = {
  before: number;
  afterStart: number;
};

export function getCollapsePlan(
  total: number,
  maxItems: number,
  itemsBeforeCollapse: number,
  itemsAfterCollapse: number | undefined,
): CollapsePlan | null {
  if (total <= maxItems) return null;

  const before = itemsBeforeCollapse;
  const after = itemsAfterCollapse ?? maxItems - before;

  if (after <= 0 || before + after >= total) return null;

  return {
    before,
    afterStart: total - after,
  };
}

/* Avatar component tokens — override these to customise avatars. */
:root {
  /* Per-size dimensions */
  --avatar-xs-size: 16px;
  --avatar-sm-size: 20px;
  --avatar-md-size: 24px;
  --avatar-lg-size: 28px;
  --avatar-xl-size: 32px;
  --avatar-2xl-size: 40px;
  --avatar-3xl-size: 46px;

  /* Per-size square radii (frappe-ui v1) */
  --avatar-xs-radius: 4px;
  --avatar-sm-radius: 5px;
  --avatar-md-radius: 5px;
  --avatar-lg-radius: 6px;
  --avatar-xl-radius: 6px;
  --avatar-2xl-radius: 8px;
  --avatar-3xl-radius: 10px;

  /* Per-size initials font sizes */
  --avatar-xs-font-size: 11px;
  --avatar-sm-font-size: 13px;
  --avatar-md-font-size: 14px;
  --avatar-lg-font-size: 14px;
  --avatar-xl-font-size: 16px;
  --avatar-2xl-font-size: 18px;
  --avatar-3xl-font-size: 20px;

  /* Per-size fallback icon sizes */
  --avatar-xs-icon-size: 10px;
  --avatar-sm-icon-size: 12px;
  --avatar-md-icon-size: 14px;
  --avatar-lg-icon-size: 16px;
  --avatar-xl-icon-size: 18px;
  --avatar-2xl-icon-size: 22px;
  --avatar-3xl-icon-size: 24px;

  /* Surfaces */
  --avatar-bg: var(--surface-gray-2);
  --avatar-fg: var(--ink-gray-5);

  /* Indicator shell — slot content fills the shell */
  --avatar-status-icon-size: 6px;
  --avatar-status-bg: var(--surface-base);
  --avatar-status-ring: var(--surface-base);
  --avatar-status-ring-width: 2px;
}

/* Avatar group component tokens — override these to customise avatar stacks. */
:root {
  --avatar-group-ring: var(--surface-base);
  --avatar-group-ring-width: 2px;

  --avatar-group-overlap-xs: 2px;
  --avatar-group-overlap-sm: 4px;
  --avatar-group-overlap-md: 4px;
  --avatar-group-overlap-lg: 5px;
  --avatar-group-overlap-xl: 4px;
  --avatar-group-overlap-2xl: 6px;
  --avatar-group-overlap-3xl: 8px;

  --avatar-group-label-fg: var(--ink-gray-5);

  --avatar-group-label-xs-font-size: 11px;
  --avatar-group-label-sm-font-size: 11px;
  --avatar-group-label-md-font-size: 14px;
  --avatar-group-label-lg-font-size: 14px;
  --avatar-group-label-xl-font-size: 16px;
  --avatar-group-label-2xl-font-size: 18px;
  --avatar-group-label-3xl-font-size: 20px;
}

/* Badge component tokens — override these to customise badges. */
:root {
  --badge-gap: 4px;
  --badge-radius: var(--radius-full);

  /* Size: sm */
  --badge-sm-height: 16px;
  --badge-sm-px: 6px;
  --badge-sm-font-size: 12px;
  --badge-sm-icon-size: 10px;

  /* Size: md */
  --badge-md-height: 20px;
  --badge-md-px: 6px;
  --badge-md-font-size: 12px;
  --badge-md-icon-size: 10px;

  /* Size: lg */
  --badge-lg-height: 24px;
  --badge-lg-px: 8px;
  --badge-lg-font-size: 13px;
  --badge-lg-icon-size: 12px;
}

/* Breadcrumb component tokens — override these to customise breadcrumbs. */
:root {
  --breadcrumb-list-gap: 2px;
  --breadcrumb-item-radius: var(--radius-4);
  --breadcrumb-ellipsis-radius: var(--radius-4);

  /* duration-press-hover: 120–180ms for hover and press feedback */
  --breadcrumb-transition-duration: 150ms;
  --breadcrumb-transition-easing: ease-out;

  /* ux-fitts-hit-area: invisible expansion beyond visible bounds */
  --breadcrumb-hit-inset: -6px -8px;

  --breadcrumb-link-fg: var(--ink-gray-5);
  --breadcrumb-link-hover-fg: var(--ink-gray-7);
  --breadcrumb-page-fg: var(--ink-gray-9);
  --breadcrumb-separator-fg: var(--ink-gray-4);

  /* Size: sm — ux-fitts-target-size: min 32px interactive height */
  --breadcrumb-sm-py: 3px;
  --breadcrumb-sm-px: 4px;
  --breadcrumb-sm-font-size: 14px;
  --breadcrumb-sm-icon-size: 16px;
  --breadcrumb-sm-min-height: 32px;
  --breadcrumb-sm-ellipsis-size: 32px;

  /* Size: md */
  --breadcrumb-md-py: 5px;
  --breadcrumb-md-px: 5px;
  --breadcrumb-md-font-size: 16px;
  --breadcrumb-md-icon-size: 16px;
  --breadcrumb-md-min-height: 32px;
  --breadcrumb-md-ellipsis-size: 32px;

  /* Collapsed items menu (ellipsis dropdown) */
  --breadcrumb-menu-min-width: 160px;
  --breadcrumb-menu-radius: var(--radius-6);
  --breadcrumb-menu-border: var(--outline-gray-1);
  --breadcrumb-menu-bg: var(--surface-elevation-2);
  --breadcrumb-menu-fg: var(--ink-gray-8);
  --breadcrumb-menu-shadow: var(--shadow-md);
  --breadcrumb-menu-item-radius: var(--radius-3);
  --breadcrumb-menu-item-px: 8px;
  --breadcrumb-menu-item-py: 6px;
  --breadcrumb-menu-item-font-size: 14px;
  --breadcrumb-menu-item-highlight-bg: var(--surface-gray-2);
  --breadcrumb-menu-item-highlight-fg: var(--ink-gray-8);
}

/* Button component tokens — override these to customise the button. */
:root {
  /* Size: xs */
  --btn-xs-height: 24px;
  --btn-xs-px: 6px;
  --btn-xs-radius: var(--radius-3);
  --btn-xs-font-size: 12px;

  /* Size: sm */
  --btn-sm-height: 28px;
  --btn-sm-px: 8px;
  --btn-sm-radius: var(--radius-4);
  --btn-sm-font-size: 14px;

  /* Size: md */
  --btn-md-height: 32px;
  --btn-md-px: 10px;
  --btn-md-radius: var(--radius-4);
  --btn-md-font-size: 14px;

  /* Size: lg */
  --btn-lg-height: 40px;
  --btn-lg-px: 12px;
  --btn-lg-radius: var(--radius-5);
  --btn-lg-font-size: 16px;
}

/* Checkbox component tokens — mirrors frappe-ui v1 toggle geometry. */
:root {
  --checkbox-xs-size: 13px;
  --checkbox-sm-size: 14px;
  --checkbox-md-size: 16px;
  --checkbox-radius: var(--radius-1);
  --checkbox-padded-radius: var(--radius-4);
  --checkbox-label-gap: 8px;

  --checkbox-xs-height: 24px;
  --checkbox-sm-height: 28px;
  --checkbox-md-height: 32px;

  --input-description-font-size: 13px;
}

/* Label component tokens — mirrors frappe-ui v1 FormLabel. */
:root {
  --label-font-size: 13px;
  --label-font-weight: 420;
  --label-color: var(--ink-gray-6);
  --label-disabled-color: var(--ink-gray-4);
  --label-required-color: var(--ink-red-5);
}

/* Switch component tokens — mirrors frappe-ui v1 toggle geometry. */
:root {
  --switch-radius: var(--radius-full);
  --switch-padded-radius: var(--radius-4);

  --switch-xs-height: 14px;
  --switch-xs-width: 24px;
  --switch-xs-thumb-size: 10px;
  --switch-xs-travel: 10px;

  --switch-sm-height: 16px;
  --switch-sm-width: 26px;
  --switch-sm-thumb-size: 12px;
  --switch-sm-travel: 10px;

  --switch-md-height: 20px;
  --switch-md-width: 32px;
  --switch-md-thumb-size: 14px;
  --switch-md-travel: 12px;

  --input-description-font-size: 13px;
}

/* TextInput component tokens — mirrors frappe-ui v1 control geometry. */
:root {
  /* Size: xs (24px) */
  --input-xs-height: 24px;
  --input-xs-radius: var(--radius-3);
  --input-xs-font-size: 12px;

  /* Size: sm (28px) */
  --input-sm-height: 28px;
  --input-sm-radius: var(--radius-4);
  --input-sm-font-size: 14px;

  /* Size: md (32px) */
  --input-md-height: 32px;
  --input-md-radius: var(--radius-4);
  --input-md-font-size: 14px;

  /* Size: lg (40px) */
  --input-lg-height: 40px;
  --input-lg-radius: var(--radius-5);
  --input-lg-font-size: 16px;

  --input-description-font-size: 13px;
}

/* Textarea component tokens — mirrors frappe-ui v1 textarea geometry. */
:root {
  --input-xs-radius: var(--radius-3);
  --input-sm-radius: var(--radius-4);
  --input-md-radius: var(--radius-4);
  --input-lg-radius: var(--radius-5);

  --textarea-xs-min-height: 32px;
  --textarea-sm-min-height: 36px;
  --textarea-md-min-height: 40px;
  --textarea-lg-min-height: 44px;
  --textarea-font-size: 13px;

  --input-description-font-size: 13px;
}
